import re
import json
from moler.exceptions import ParsingDone, CommandFailure
from moler.helpers import convert_to_int
from ta_moler.cmd.shared.aashell.genericaashell import GenericAashell

__author__ = 'Tomasz Krol'
__copyright__ = 'Copyright (C) 2020 Nokia'
__email__ = 'tomasz.krol@nokia.com'


class GetResourcesUsage(GenericAashell):
    """getResourcesUsage command class."""

    def __init__(self, connection, options, prompt=None, newline_chars=None, runner=None):
        """
        Command getResourcesUsage.

        :param connection: moler connection to device, terminal when command is executed
        :param options: parameter with which the command will be executed
        :param prompt: Prompt of the starting shell
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(GetResourcesUsage, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars,
                                                runner=runner)
        self.options = options
        self.current_ret = {}

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = 'getResourcesUsage'
        if self.options:
            cmd = f'{cmd} {self.options}'
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Execute all parsing methods.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_command_failure(line)
                self._parse_response(line)
            except ParsingDone:
                pass
        return super(GetResourcesUsage, self).on_new_line(line, is_full_line)

    # Process 'WRONG' not registered to AaShell
    _re_failure = re.compile(r"(?P<ERROR>Process .* not registered to AaShell)")

    def _parse_command_failure(self, line):
        """
        Raise exception CommandFailure if process is not registered to AaShell.

        :param line: line to be parsed
        :return: None but raises CommandFailure.
        """
        if self._regex_helper.search_compiled(GetResourcesUsage._re_failure, line):
            self.set_exception(CommandFailure(self, f"ERROR: {self._regex_helper.group('ERROR')}"))
            raise ParsingDone

    # {"ResourcesUsageInfoResponses": [{"ENBC .... ]}
    _re_response = re.compile(r'(?P<RESPONSE>{"ResourcesUsage.*]})')

    def _parse_response(self, line):
        """
        Parse ResourcesUsageInfoResponses.

        :param line: line to be parsed
        """
        if self._regex_helper.search_compiled(GetResourcesUsage._re_response, line):
            self.current_ret = json.loads(self._regex_helper.group("RESPONSE"), object_hook=convert_to_int)
            raise ParsingDone


